SELECT appointment_start + INTERVAL '8 hours' AS appointment_start
FROM {{ $('Table Name').item.json['Table Name'] }}
WHERE id = 1
LIMIT 1;

SELECT EXISTS (
  SELECT 1
  FROM information_schema.tables
  WHERE table_schema = 'public'
  AND table_name = 'n8n_info_record_{{ $('WhatsApp Trigger').item.json.contacts[0].wa_id }}'
) AS table_exists;

SELECT EXISTS (
    SELECT 1
    FROM {{ $('Table Name').item.json['Table Name'] }}
    WHERE language IS NULL
) AS language_is_null;
